18	        String householdId = HouseholdId.of(owner.getLastName(), owner.getPostcode());
19	        Integer maxMemberLevel = null;
20	        for (Owner member : ownerRepository.findAll()) {
21	            if (member.getId() != null && member.getId().equals(owner.getId())) {
22	                continue;
23	            }
24	            if (!householdId.equals(HouseholdId.of(member.getLastName(), member.getPostcode()))) {
25	                continue;
