28	                member.getNamesakeCount(), member.getEmail(), member.getRegistrationDate()));
29	            if (maxMemberLevel == null || memberLevel > maxMemberLevel) {
30	                maxMemberLevel = memberLevel;
31	            }
32	        }
33	        return maxMemberLevel == null ? rawLevel : Math.min(rawLevel, maxMemberLevel + 1);
